(function(global){
'use strict';
const FT={};
FT.humanBytes=(n)=>{if(!Number.isFinite(n))return '—';if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(n<10240?1:0)+' KB';return (n/1048576).toFixed(n<10485760?1:0)+' MB';};
FT.clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
FT.nextFrame=()=>new Promise(r=>requestAnimationFrame(()=>r()));
FT.toBlob=(canvas,type='image/jpeg',quality=.9)=>new Promise((res,rej)=>canvas.toBlob(b=>b?res(b):rej(new Error('Could not encode image.')),type,quality));
FT.fileToImage=async(file)=>{
  if(!file||!/^image\/(jpeg|png|webp)$/i.test(file.type))throw new Error('Choose a JPG, PNG or WebP image.');
  if(file.size>30*1024*1024)throw new Error('Image is too large. Maximum file size is 30 MB.');
  const url=URL.createObjectURL(file);
  try{
    const img=new Image(); img.decoding='async'; img.src=url; await img.decode();
    if(!img.naturalWidth||!img.naturalHeight)throw new Error('Could not read this image.');
    const dpi=await FT.readDpi(file).catch(()=>({x:null,y:null,source:'none'}));
    return {img,width:img.naturalWidth,height:img.naturalHeight,size:file.size,type:file.type,name:file.name,dpi,url};
  }catch(e){URL.revokeObjectURL(url);throw e;}
};
FT.releaseImage=(obj)=>{if(obj&&obj.url)URL.revokeObjectURL(obj.url);};
FT.canvas=(w,h)=>{const c=document.createElement('canvas');c.width=Math.max(1,Math.round(w));c.height=Math.max(1,Math.round(h));return c;};
FT.unitToPx=(value,unit,dpi=300)=>{value=Number(value)||0;dpi=Number(dpi)||300; if(unit==='px')return Math.round(value); if(unit==='cm')return Math.round(value/2.54*dpi); if(unit==='mm')return Math.round(value/25.4*dpi); if(unit==='in')return Math.round(value*dpi); return Math.round(value);};
FT.pxToUnits=(px,dpi=300)=>({in:px/dpi,cm:px/dpi*2.54,mm:px/dpi*25.4});
FT.drawFit=(ctx,img,dw,dh,mode='fit',bg=null,sourceRect=null)=>{
  ctx.clearRect(0,0,dw,dh);
  if(bg){ctx.fillStyle=bg;ctx.fillRect(0,0,dw,dh);}
  let sx=0,sy=0,sw=img.naturalWidth||img.width,sh=img.naturalHeight||img.height;
  if(sourceRect){({sx,sy,sw,sh}=sourceRect);}
  if(mode==='stretch'){ctx.drawImage(img,sx,sy,sw,sh,0,0,dw,dh);return;}
  const sr=sw/sh, dr=dw/dh;
  if(mode==='fill'||mode==='crop'){
    if(sr>dr){const nsw=sh*dr;sx+=(sw-nsw)/2;sw=nsw;}else{const nsh=sw/dr;sy+=(sh-nsh)/2;sh=nsh;}
    ctx.drawImage(img,sx,sy,sw,sh,0,0,dw,dh);
  }else{
    let rw=dw,rh=dh;if(sr>dr)rh=dw/sr;else rw=dh*sr;
    ctx.drawImage(img,sx,sy,sw,sh,(dw-rw)/2,(dh-rh)/2,rw,rh);
  }
};
FT.cropRect=(iw,ih,ratio,zoom=1,posX=0,posY=0)=>{
  zoom=FT.clamp(Number(zoom)||1,1,3); posX=FT.clamp(Number(posX)||0,-1,1); posY=FT.clamp(Number(posY)||0,-1,1);
  let sw=iw,sh=ih;if(iw/ih>ratio)sw=ih*ratio;else sh=iw/ratio;
  sw/=zoom;sh/=zoom; const maxX=(iw-sw)/2,maxY=(ih-sh)/2;
  const sx=FT.clamp((iw-sw)/2+posX*maxX,0,iw-sw), sy=FT.clamp((ih-sh)/2+posY*maxY,0,ih-sh);
  return {sx,sy,sw,sh};
};
FT.trimRect=(img,threshold=36)=>{
  const max=1400,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight));
  const w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));
  const c=FT.canvas(w,h),x=c.getContext('2d',{willReadFrequently:true});x.drawImage(img,0,0,w,h);
  const d=x.getImageData(0,0,w,h).data;
  const corners=[[0,0],[w-1,0],[0,h-1],[w-1,h-1]].map(([cx,cy])=>{const i=(cy*w+cx)*4;return [d[i],d[i+1],d[i+2],d[i+3]];});
  const bg=[0,1,2].map(k=>Math.round(corners.reduce((s,c)=>s+c[k],0)/4));
  let minX=w,minY=h,maxX=-1,maxY=-1;
  for(let y=0;y<h;y++){for(let xx=0;xx<w;xx++){const i=(y*w+xx)*4,a=d[i+3];if(a<18)continue;const diff=Math.abs(d[i]-bg[0])+Math.abs(d[i+1]-bg[1])+Math.abs(d[i+2]-bg[2]);if(diff>threshold){if(xx<minX)minX=xx;if(xx>maxX)maxX=xx;if(y<minY)minY=y;if(y>maxY)maxY=y;}}}
  if(maxX<0)return {sx:0,sy:0,sw:img.naturalWidth,sh:img.naturalHeight};
  const pad=Math.max(2,Math.round(Math.max(maxX-minX,maxY-minY)*.04));minX=Math.max(0,minX-pad);minY=Math.max(0,minY-pad);maxX=Math.min(w-1,maxX+pad);maxY=Math.min(h-1,maxY+pad);
  return {sx:minX/scale,sy:minY/scale,sw:(maxX-minX+1)/scale,sh:(maxY-minY+1)/scale};
};
FT.encodeTarget=async(canvas,mime,targetBytes,opts={})=>{
  const minQ=FT.clamp(Number(opts.minQuality)||.35,.15,.95),maxQ=FT.clamp(Number(opts.maxQuality)||.94,minQ,1); const allowResize=!!opts.allowResize;
  if(!targetBytes){const blob=await FT.toBlob(canvas,mime,maxQ);return {blob,quality:maxQ,scale:1,reached:true};}
  let working=canvas,best=null,smallest=null,totalScale=1;
  const lossy=/jpeg|webp/.test(mime);
  for(let resizePass=0;resizePass<(allowResize?8:1);resizePass++){
    if(lossy){let lo=minQ,hi=maxQ;for(let i=0;i<9;i++){const q=(lo+hi)/2;const b=await FT.toBlob(working,mime,q);const rec={blob:b,quality:q,scale:totalScale,reached:b.size<=targetBytes};if(!smallest||b.size<smallest.blob.size)smallest=rec;if(b.size<=targetBytes){if(!best||b.size>best.blob.size)best=rec;lo=q;}else hi=q;await FT.nextFrame();}}
    else {const b=await FT.toBlob(working,mime);const rec={blob:b,quality:1,scale:totalScale,reached:b.size<=targetBytes};if(!smallest||b.size<smallest.blob.size)smallest=rec;if(rec.reached)best=rec;}
    if(best)return best;if(!allowResize)break;
    totalScale*=.88;const nw=Math.max(64,Math.round(canvas.width*totalScale)),nh=Math.max(64,Math.round(canvas.height*totalScale));const next=FT.canvas(nw,nh);next.getContext('2d').drawImage(canvas,0,0,nw,nh);working=next;await FT.nextFrame();
  }
  return smallest||{blob:await FT.toBlob(canvas,mime,minQ),quality:minQ,scale:totalScale,reached:false};
};
function crc32(bytes){let table=crc32.table;if(!table){table=crc32.table=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;table[n]=c>>>0;}}let c=0xffffffff;for(let i=0;i<bytes.length;i++)c=table[(c^bytes[i])&255]^(c>>>8);return (c^0xffffffff)>>>0;}
function u32be(n){return new Uint8Array([(n>>>24)&255,(n>>>16)&255,(n>>>8)&255,n&255]);}
FT.patchDpi=async(blob,mime,dpi)=>{dpi=Math.round(Number(dpi)||0);if(!dpi||dpi<1)return blob;const arr=new Uint8Array(await blob.arrayBuffer());
  if(/jpeg/.test(mime)){
    if(arr[0]!==0xff||arr[1]!==0xd8)return blob;let p=2,found=false;
    while(p+4<arr.length&&arr[p]===0xff){const marker=arr[p+1],len=(arr[p+2]<<8)|arr[p+3];if(marker===0xe0&&p+14<arr.length&&String.fromCharCode(...arr.slice(p+4,p+9))==='JFIF\0'){arr[p+11]=1;arr[p+12]=(dpi>>8)&255;arr[p+13]=dpi&255;arr[p+14]=(dpi>>8)&255;arr[p+15]=dpi&255;found=true;break;}if(marker===0xda||!len)break;p+=2+len;}
    if(found)return new Blob([arr],{type:mime});
    const seg=new Uint8Array([0xff,0xe0,0x00,0x10,0x4a,0x46,0x49,0x46,0x00,0x01,0x02,0x01,(dpi>>8)&255,dpi&255,(dpi>>8)&255,dpi&255,0,0]);
    return new Blob([arr.slice(0,2),seg,arr.slice(2)],{type:mime});
  }
  if(/png/.test(mime)){
    const sig=[137,80,78,71,13,10,26,10];if(!sig.every((v,i)=>arr[i]===v))return blob;const ppm=Math.round(dpi/0.0254);const data=new Uint8Array(9);data.set(u32be(ppm),0);data.set(u32be(ppm),4);data[8]=1;const type=new TextEncoder().encode('pHYs');const crcInput=new Uint8Array(13);crcInput.set(type,0);crcInput.set(data,4);const chunk=new Uint8Array(21);chunk.set(u32be(9),0);chunk.set(type,4);chunk.set(data,8);chunk.set(u32be(crc32(crcInput)),17);
    let pos=8,oldStart=-1,oldEnd=-1;while(pos+12<=arr.length){const len=(arr[pos]<<24)|(arr[pos+1]<<16)|(arr[pos+2]<<8)|arr[pos+3];const typ=String.fromCharCode(...arr.slice(pos+4,pos+8));if(typ==='pHYs'){oldStart=pos;oldEnd=pos+12+len;break;}if(typ==='IDAT')break;pos+=12+len;}
    if(oldStart>=0)return new Blob([arr.slice(0,oldStart),chunk,arr.slice(oldEnd)],{type:mime});
    const ihdrLen=(arr[8]<<24)|(arr[9]<<16)|(arr[10]<<8)|arr[11];const insert=8+12+ihdrLen;return new Blob([arr.slice(0,insert),chunk,arr.slice(insert)],{type:mime});
  }
  return blob;
};
FT.readDpi=async(file)=>{const a=new Uint8Array(await file.slice(0,262144).arrayBuffer());const type=file.type;
  if(/jpeg/.test(type)&&a[0]===0xff&&a[1]===0xd8){let p=2;while(p+16<a.length&&a[p]===0xff){const marker=a[p+1],len=(a[p+2]<<8)|a[p+3];if(marker===0xe0&&String.fromCharCode(...a.slice(p+4,p+9))==='JFIF\0'){const unit=a[p+11],xd=(a[p+12]<<8)|a[p+13],yd=(a[p+14]<<8)|a[p+15];if(unit===1)return{x:xd,y:yd,source:'JFIF'};if(unit===2)return{x:Math.round(xd*2.54),y:Math.round(yd*2.54),source:'JFIF'};}if(marker===0xda||!len)break;p+=2+len;}}
  if(/png/.test(type)){let p=8;while(p+21<a.length){const len=(a[p]<<24)|(a[p+1]<<16)|(a[p+2]<<8)|a[p+3];const typ=String.fromCharCode(...a.slice(p+4,p+8));if(typ==='pHYs'){const x=((a[p+8]<<24)|(a[p+9]<<16)|(a[p+10]<<8)|a[p+11])>>>0,y=((a[p+12]<<24)|(a[p+13]<<16)|(a[p+14]<<8)|a[p+15])>>>0,unit=a[p+16];if(unit===1)return{x:Math.round(x*.0254),y:Math.round(y*.0254),source:'pHYs'};}if(typ==='IDAT')break;p+=12+len;}}
  return{x:null,y:null,source:'none'};
};
FT.mimeFromFormat=(format,original='image/jpeg')=>{if(format==='keep')return original;if(format==='jpg'||format==='jpeg')return'image/jpeg';if(format==='png')return'image/png';if(format==='webp')return'image/webp';return original;};
FT.extFromMime=(m)=>/png/.test(m)?'png':/webp/.test(m)?'webp':'jpg';
FT.download=(blob,name)=>{const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2500);};
FT.previewBlob=(blob,img)=>{const old=img.dataset.objectUrl;if(old)URL.revokeObjectURL(old);const u=URL.createObjectURL(blob);img.dataset.objectUrl=u;img.src=u;};
global.FastooleeImageCore=FT;
})(window);
